    id: "aied-015",
    slug: "chatgpt-supported-efl-writing-ai-literacy-learner-autonomy",
    title: "AI literacy and mediated learner autonomy in ChatGPT-supported EFL writing: a qualitative study at a Palestinian university",
    authors: ["Bilal Hamamra", "Asma Abdullah", "Sanadil Alawi"],
    venue: "International Journal of Educational Technology in Higher Education",
